'use client'

import { useEffect, useMemo, useRef, useState } from 'react'
import useSWR from 'swr'
import { createClient } from '@/lib/supabase/client'
import type { AnalysisRecord, AnalysisResponse } from '@/lib/analysis'
import { AnalysisResultPanel } from '@/components/analysis-result'
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import { Activity, AlertTriangle, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, BookOpen, Bot, Building2, Check, CheckCircle2, ChevronDown, ChevronRight, CircleHelp, Cloud, Copy, Cpu, Download, Eye, FileClock, FileImage, FileText, Filter, Globe2, GraduationCap, HeartHandshake, History, ImagePlus, KeyRound, LayoutDashboard, Link2, LockKeyhole, LogIn, LogOut, Menu, MessageSquareWarning, MoreHorizontal, Network, Radar, Search, Send, Settings, Shield, ShieldAlert, ShieldCheck, Sparkles, Upload, UserRound, X, Zap } from 'lucide-react'

type SessionUser = { id: string; email: string; name: string }
type Props = { user: SessionUser | null; initialSection?: string }
type NavItem = { key: string; label: string; icon: typeof LayoutDashboard; group: string }
const navItems: NavItem[] = [
  { key:'overview', label:'Overview', icon:LayoutDashboard, group:'VISÃO GERAL' },
  { key:'scanner', label:'Threat Scanner', icon:Radar, group:'VISÃO GERAL' },
  { key:'history', label:'Analysis History', icon:History, group:'VISÃO GERAL' },
  { key:'intelligence', label:'Threat Intelligence', icon:Activity, group:'VISÃO GERAL' },
  { key:'education', label:'Digital Education', icon:GraduationCap, group:'SEGURANÇA & COMUNIDADE' },
  { key:'reports', label:'Reports', icon:FileText, group:'SEGURANÇA & COMUNIDADE' },
  { key:'my-reports', label:'Minhas denúncias', icon:MessageSquareWarning, group:'SEGURANÇA & COMUNIDADE' },
  { key:'plans', label:'Meu plano', icon:Zap, group:'GERENCIAMENTO' },
 { key:'settings', label:'Configurações', icon:Settings, group:'GERENCIAMENTO' },
]
const chartTooltip = { contentStyle:{background:'#111827',border:'1px solid #253047',borderRadius:12,color:'#f8fafc',fontSize:12}, itemStyle:{color:'#dbe4f2'}, labelStyle:{color:'#94a3b8'} }
const recommendations = ['Ative a autenticação em dois fatores nos serviços mais importantes.','Desconfie de mensagens que criam urgência ou pedem dados pessoais.','Confira o endereço completo antes de abrir links recebidos.']
const lessons = [
  {icon:MailIcon,title:'Como identificar phishing',text:'Aprenda a reconhecer mensagens e links criados para roubar dados.',tag:'5 min',color:'purple'},
  {icon:ShieldAlert,title:'Golpes bancários',text:'Sinais de falsas centrais, boletos e transferências suspeitas.',tag:'7 min',color:'cyan'},
  {icon:Globe2,title:'Sites falsos',text:'Confira domínio, certificado e detalhes que passam despercebidos.',tag:'4 min',color:'green'},
  {icon:UserRound,title:'Engenharia social',text:'Entenda como golpistas usam confiança e pressão emocional.',tag:'6 min',color:'amber'},
]
function MailIcon(props: {size?:number}) { return <MessageSquareWarning size={props.size ?? 20}/> }
const statusLabel: Record<string,string> = {received:'Recebida',reviewing:'Em análise',investigating:'Em investigação',confirmed:'Confirmada',unconfirmed:'Não confirmada',closed:'Encerrada'}
const riskLabels: Record<AnalysisRecord['risk_level'],string> = {low:'Baixo',moderate:'Moderado',high:'Alto',critical:'Crítico'}
const riskColors: Record<AnalysisRecord['risk_level'],string> = {low:'#10b981',moderate:'#f59e0b',high:'#f97316',critical:'#ef4444'}
function getAnalysisTrend(rows:AnalysisRecord[]){return Array.from({length:7},(_,index)=>{const date=new Date();date.setDate(date.getDate()-(6-index));const key=date.toLocaleDateString('sv-SE');const dayRows=rows.filter(row=>new Date(row.created_at).toLocaleDateString('sv-SE')===key);return{day:new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(date).replace('.',''),scans:dayRows.length,threats:dayRows.filter(row=>row.risk_score>=65).length}})}
function getAnalysisCategories(rows:AnalysisRecord[]){const counts=new Map<string,number>();rows.forEach(row=>row.indicators.forEach(indicator=>counts.set(indicator.category,(counts.get(indicator.category)??0)+1)));const colors=['#8b5cf6','#22d3ee','#f59e0b','#ec4899','#10b981'];return Array.from(counts,([name,value],index)=>({name,value,color:colors[index%colors.length]})).sort((a,b)=>b.value-a.value).slice(0,5)}
function getRiskDistribution(rows:AnalysisRecord[]){return(['low','moderate','high','critical'] as const).map(level=>{const value=rows.length?Math.round(rows.filter(row=>row.risk_level===level).length/rows.length*100):0;return{name:riskLabels[level],value,color:riskColors[level]}})}

function Brand({compact=false}:{compact?:boolean}) { return <div className="brand"><span className="brand-symbol"><Shield size={20}/><span className="brand-eye"/></span>{!compact&&<span>Vig<span>IA</span></span>}</div> }
function SectionTitle({eyebrow,title,description,action}:{eyebrow:string,title:string,description:string,action?:React.ReactNode}) { return <div className="section-title"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div>{action}</div> }
function Panel({title,subtitle,action,children,className=''}:{title:string;subtitle?:string;action?:React.ReactNode;children:React.ReactNode;className?:string}) { return <section className={`panel ${className}`}><div className="panel-head"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>{children}</section> }
function Metric({label,value,change,icon:Icon,tone='purple'}:{label:string;value:string;change:string;icon:typeof Activity;tone?:string}) { return <div className="metric-card"><div className="metric-top"><span>{label}</span><span className={`metric-icon ${tone}`}><Icon size={17}/></span></div><div className="metric-value">{value}</div><div className="metric-change"><span><ArrowUpRight size={13}/>{change}</span><small>dados da sua conta</small></div></div> }

export default function VigiaDashboard({user:initialUser,initialSection}:Props) {
  const validSection=navItems.some(item=>item.key===initialSection)?initialSection!:'overview'
  const [active,setActive]=useState(validSection)
  const [scannerTab,setScannerTab]=useState<'url'|'message'|'image'>('url')
  const [scanText,setScanText]=useState('')
  const [scanResult,setScanResult]=useState(false)
  const [analysisResult,setAnalysisResult]=useState<AnalysisResponse|null>(null)
  const [extractedText,setExtractedText]=useState('')
  const [scanStep,setScanStep]=useState('Aguardando conteúdo')
  const [scanning,setScanning]=useState(false)
  const [selectedFile,setSelectedFile]=useState<File|null>(null)
  const [filePreview,setFilePreview]=useState('')
  const [mobileOpen,setMobileOpen]=useState(false)
  const [sidebarCollapsed,setSidebarCollapsed]=useState(false)
  const [notice,setNotice]=useState('')
  const [user,setUser]=useState(initialUser)
  const [reports,setReports]=useState<Record<string,unknown>[]>([])
  const { data: analyses = [], error: analysesError, mutate: refreshAnalyses } = useSWR<AnalysisRecord[]>(user ? ['analyses', user.id] : null, async () => {
    const { data, error } = await createClient().from('analyses').select('id,content_type,risk_score,risk_level,indicators,explanation,recommendations,processing_status,origin,created_at').order('created_at', { ascending: false }).limit(500)
    if (error) throw error
    return (data ?? []) as AnalysisRecord[]
  })
  const [reportForm,setReportForm]=useState(false)
  const [reportBusy,setReportBusy]=useState(false)
  const [reportTitle,setReportTitle]=useState('')
  const [reportDescription,setReportDescription]=useState('')
  const [reportCategory,setReportCategory]=useState('Phishing')
  const [reportUrl,setReportUrl]=useState('')
  const [evidenceFiles,setEvidenceFiles]=useState<File[]>([])
  const [educationScore,setEducationScore]=useState<number|null>(null)
  const [quizChoice,setQuizChoice]=useState('')
  const [settingsTab,setSettingsTab]=useState('profile')
  const fileRef=useRef<HTMLInputElement>(null)
  const activeItem=navItems.find(item=>item.key===active)??navItems[0]
  const userName=user?.name||'Giovanni'
  const grouped=useMemo(()=>Array.from(new Set(navItems.map(item=>item.group))),[])

  function flash(text:string){setNotice(text);window.setTimeout(()=>setNotice(''),3200)}
  async function startScan(){
    if(!user){window.location.assign(`/auth/login?next=${encodeURIComponent('/?section=scanner')}`);return}
    if(!scanText.trim()&&scannerTab!=='image'){flash('Insira um conteúdo para analisar.');return}
    if(scannerTab==='image'&&!selectedFile){flash('Selecione uma imagem antes de iniciar.');return}
    setScanResult(false);setAnalysisResult(null);setExtractedText('');setScanning(true)
    let content=scanText.trim()
    try{
      if(scannerTab==='image'&&selectedFile){
        setScanStep('Validando arquivo de imagem')
        const header=new Uint8Array(await selectedFile.slice(0,12).arrayBuffer())
        const validPng=header[0]===0x89&&header[1]===0x50&&header[2]===0x4e&&header[3]===0x47
        const validJpeg=header[0]===0xff&&header[1]===0xd8&&header[2]===0xff
        const validWebp=String.fromCharCode(...header.slice(0,4))==='RIFF'&&String.fromCharCode(...header.slice(8,12))==='WEBP'
        if(!validPng&&!validJpeg&&!validWebp)throw new Error('O conteúdo do arquivo não corresponde a uma imagem PNG, JPG ou WEBP válida.')
        setScanStep('Extraindo texto com OCR local')
        const {createWorker}=await import('tesseract.js')
        const worker=await createWorker('por+eng',1,{logger:message=>{if(message.status==='recognizing text')setScanStep(`OCR em andamento · ${Math.round((message.progress??0)*100)}%`)}})
        try{const result=await worker.recognize(selectedFile);content=result.data.text.trim()}finally{await worker.terminate()}
        setExtractedText(content)
        if(!content)throw new Error('Nenhum texto legível foi encontrado na imagem. Tente uma captura mais nítida.')
      }
      setScanStep('Analisando sinais com inteligência artificial')
      const response=await fetch('/api/analyses',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({type:scannerTab,content})})
      const payload=await response.json() as AnalysisResponse & {error?:string}
      if(!response.ok)throw new Error(payload.error||'Não foi possível concluir a análise.')
      setAnalysisResult(payload);setScanResult(true);setScanStep('Análise concluída');await refreshAnalyses()
    }catch(error){flash(error instanceof Error?error.message:'O serviço está temporariamente indisponível. Tente novamente.');setScanStep('Falha na análise')}
    finally{setScanning(false)}
  }
  function selectFile(file?:File){if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){flash('Formato não aceito. Use PNG, JPG ou WEBP.');return}if(file.size>5*1024*1024){flash('O arquivo deve ter até 5 MB.');return}if(filePreview)URL.revokeObjectURL(filePreview);setSelectedFile(file);setFilePreview(URL.createObjectURL(file));setScanResult(false);setAnalysisResult(null)}
  async function loadReports(){if(!user){setActive('my-reports');flash('Entre na sua conta para acessar suas denúncias privadas.');return}const supabase=createClient();const {data,error}=await supabase.from('reports').select('id,category,title,platform,status,created_at,updated_at').order('created_at',{ascending:false});if(error){flash('Não foi possível carregar suas denúncias.');return}const reportRows=data??[];if(reportRows.length){const {data:attachments}=await supabase.from('report_attachments').select('report_id,file_name,storage_path').in('report_id',reportRows.map(report=>report.id));const attachmentRows=await Promise.all((attachments??[]).map(async item=>{const {data}=await supabase.storage.from('report-evidence').createSignedUrl(item.storage_path,3600);return {...item,signed_url:data?.signedUrl??''}}));setReports(reportRows.map(report=>({...report,attachments:attachmentRows.filter(item=>item.report_id===report.id)})))}else setReports([]);setActive('my-reports')}
  useEffect(()=>{function syncSectionFromLocation(){const path=window.location.pathname;const querySection=new URLSearchParams(window.location.search).get('section');const routeSection:Record<string,string>={'/minhas-denuncias':'my-reports','/configuracoes':'settings','/meu-plano':'plans'};const section=routeSection[path]??querySection??'overview';if(navItems.some(item=>item.key===section)){setActive(section);if(section==='my-reports')void loadReports()}}window.addEventListener('popstate',syncSectionFromLocation);return()=>window.removeEventListener('popstate',syncSectionFromLocation)},[user])
  async function submitReport(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!user){flash('Entre na sua conta para enviar uma denúncia.');return}if(evidenceFiles.length>3||evidenceFiles.some(file=>file.size>5*1024*1024||!['image/png','image/jpeg','image/webp','application/pdf'].includes(file.type))){flash('Use até 3 arquivos PNG, JPG, WEBP ou PDF, com no máximo 5 MB cada.');return}setReportBusy(true);const supabase=createClient();const {data:report,error}=await supabase.from('reports').insert({user_id:user.id,category:reportCategory,title:reportTitle,description:reportDescription,suspicious_url:reportUrl||null,platform:'Web',incident_outcome:'Tentativa identificada'}).select('id').single();if(error||!report){setReportBusy(false);flash('Não foi possível enviar. Tente novamente.');return}const uploadedPaths:string[]=[];let uploadError=false;for(const file of evidenceFiles){const safeName=file.name.replace(/[^\p{L}\p{N}._-]+/gu,'_').slice(-120)||'evidencia';const storagePath=`${user.id}/${report.id}/${crypto.randomUUID()}-${safeName}`;const {error}=await supabase.storage.from('report-evidence').upload(storagePath,file,{contentType:file.type,upsert:false});if(error){uploadError=true;break}uploadedPaths.push(storagePath)}if(!uploadError&&uploadedPaths.length){const {error}=await supabase.from('report_attachments').insert(evidenceFiles.map((file,index)=>({report_id:report.id,user_id:user.id,file_name:file.name.slice(0,255),file_type:file.type,storage_path:uploadedPaths[index]})));uploadError=!!error}if(uploadError){if(uploadedPaths.length)await supabase.storage.from('report-evidence').remove(uploadedPaths);await supabase.from('reports').delete().eq('id',report.id).eq('user_id',user.id);setReportBusy(false);flash('Não foi possível armazenar as evidências. A denúncia não foi registrada; tente novamente.');return}setReportBusy(false);setReportTitle('');setReportDescription('');setReportUrl('');setEvidenceFiles([]);setReportForm(false);flash(uploadedPaths.length?'Denúncia e evidências enviadas com segurança. Obrigado por colaborar.':'Denúncia enviada com segurança. Obrigado por colaborar.');await loadReports()}
  async function signOut(){await createClient().auth.signOut();setUser(null);setActive('overview');window.history.replaceState({},'','/');flash('Você saiu da sua conta.')}

  function navTo(key:string){const privateRoutes:Record<string,string>={'my-reports':'/minhas-denuncias',settings:'/configuracoes',plans:'/meu-plano'};const destination=privateRoutes[key];if(destination&&!user){window.location.assign(`/auth/login?next=${encodeURIComponent(destination)}`);return}if(destination)window.history.pushState({},'',destination);else window.history.pushState({},'',key==='overview'?'/':`/?section=${key}`);if(key==='my-reports'){void loadReports();setMobileOpen(false);return}setActive(key);setMobileOpen(false);setScanResult(false)}
  function renderNav(){return <>{grouped.map(group=><div className="nav-group" key={group}><div className="nav-group-title">{group}</div>{navItems.filter(item=>item.group===group).map(item=>{const Icon=item.icon;return <button key={item.key} onClick={()=>navTo(item.key)} className={`nav-item ${active===item.key?'active':''}`} title={sidebarCollapsed?item.label:undefined}><Icon size={17}/><span>{item.label}</span>{active===item.key&&<span className="nav-indicator"/>}</button>})}</div>)}</>}

  return <div className={`app-shell ${sidebarCollapsed?'sidebar-is-collapsed':''}`}>
    {mobileOpen&&<button className="mobile-scrim" aria-label="Fechar navegação" onClick={()=>setMobileOpen(false)}/>}
    <aside className={`sidebar ${mobileOpen?'sidebar-open':''}`}><div className="sidebar-brand"><Brand/><button className="icon-button sidebar-collapse" aria-label={sidebarCollapsed?'Expandir menu':'Recolher menu'} aria-expanded={!sidebarCollapsed} onClick={()=>setSidebarCollapsed(value=>!value)}><ChevronRight size={16}/></button></div><div className="sidebar-scroll">{renderNav()}</div><div className="sidebar-bottom"><div className="protection-mini"><div className="mini-shield"><ShieldCheck size={17}/></div><div><strong>Proteção ativa</strong><span>Monitoramento operacional</span></div><span className="status-dot"/></div>{user&&<div className="profile-row"><div className="avatar">{userName.slice(0,1).toUpperCase()}</div><div className="profile-info"><strong>{userName}</strong><span>Plano gratuito</span></div><button className="icon-button profile-menu" onClick={()=>void signOut()} title="Sair" aria-label="Sair da conta"><LogOut size={16}/></button></div>}</div></aside>
    <main className="main-shell"><header className="topbar"><button className="icon-button mobile-menu" onClick={()=>setMobileOpen(true)} aria-label="Abrir menu"><Menu size={19}/></button><div className="breadcrumb"><span>VigIA</span><ChevronRight size={14}/><strong>{activeItem.label}</strong></div><div className="topbar-actions"><div className="search-box"><Search size={15}/><input aria-label="Buscar" placeholder="Buscar análises, alertas..." onKeyDown={e=>{if(e.key==='Enter'&&!((e.nativeEvent as KeyboardEvent).isComposing||(e.keyCode===229))){setActive('history');flash('Exibindo seu histórico demonstrativo.')}}}/><kbd>⌘ K</kbd></div><span className="system-status"><span className="status-dot"/> Sistemas operacionais</span><button className="icon-button notification-button" onClick={()=>flash('Você está em dia. Nenhum alerta novo.')} aria-label="Notificações"><Bell size={17}/><i/></button>{user?<button className="top-user" onClick={()=>navTo('settings')}><span className="avatar small">{userName.slice(0,1).toUpperCase()}</span><span>{userName}</span><ChevronDown size={14}/></button>:<a href="/auth/login" className="login-link"><LogIn size={15}/> Entrar</a>}</div></header>
      <div className="content-area">
        {active==='overview'&&<><Overview userName={userName} analyses={analyses} onScanner={()=>navTo('scanner')} onHistory={()=>navTo('history')}/>{analysesError&&<div className="table-note" role="status">Não foi possível carregar os indicadores da sua conta.</div>}</>}
        {active==='scanner'&&<Scanner tab={scannerTab} setTab={setScannerTab} scanText={scanText} setScanText={setScanText} scanning={scanning} scanStep={scanStep} result={scanResult} analysisResult={analysisResult} extractedText={extractedText} startScan={startScan} selectedFile={selectedFile} filePreview={filePreview} fileRef={fileRef} selectFile={selectFile} clearFile={()=>{if(filePreview)URL.revokeObjectURL(filePreview);setSelectedFile(null);setFilePreview('');setAnalysisResult(null);setScanResult(false)}}/>}
        {active==='history'&&<HistoryPage analyses={analyses} onScan={()=>navTo('scanner')}/>}
        {active==='intelligence'&&<Intelligence analyses={analyses}/>}
        {active==='education'&&<Education score={educationScore} setScore={setEducationScore} choice={quizChoice} setChoice={setQuizChoice}/>}
        {active==='reports'&&<Reports onOpen={()=>setReportForm(true)} onMine={()=>void loadReports()}/>}
        {active==='my-reports'&&<MyReports reports={reports} signedIn={!!user} onLogin={()=>window.location.assign('/auth/login')} onReport={()=>setReportForm(true)} onRefresh={()=>void loadReports()} onToast={flash}/>}
        {active==='plans'&&<Plans onAction={()=>flash('A contratação real ficará disponível após a integração de pagamentos. Nenhuma cobrança foi realizada.')}/>}
        {active==='settings'&&<SettingsPage user={user} tab={settingsTab} setTab={setSettingsTab} onLogin={()=>window.location.assign('/auth/login')} onToast={flash}/>}
        <footer className="app-footer"><Brand compact/><span>VigIA — Sua segurança digital começa com a informação.</span><span className="demo-disclaimer"><span className="demo-dot"/> Dados de demonstração</span></footer>
      </div>
    </main>
    {notice&&<div className="toast" role="status"><CheckCircle2 size={17}/>{notice}<button onClick={()=>setNotice('')} aria-label="Fechar"><X size={14}/></button></div>}
    {reportForm&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setReportForm(false)}}><section className="report-modal" role="dialog" aria-modal="true" aria-labelledby="report-modal-title"><div className="modal-heading"><div><span className="eyebrow">COMUNIDADE VIGIA</span><h2 id="report-modal-title">Denunciar uma ameaça</h2><p>Compartilhe informações para ajudar na análise de possíveis golpes.</p></div><button className="icon-button" onClick={()=>setReportForm(false)} aria-label="Fechar"><X size={18}/></button></div><form className="report-form" onSubmit={submitReport}><label>Categoria<select value={reportCategory} onChange={e=>setReportCategory(e.target.value)}><option>Phishing</option><option>Site fraudulento</option><option>Golpe bancário</option><option>Golpe pelo WhatsApp</option><option>Falso suporte técnico</option><option>Roubo de dados pessoais</option><option>Falso investimento</option><option>Outro</option></select></label><label>Título<input required maxLength={140} value={reportTitle} onChange={e=>setReportTitle(e.target.value)} placeholder="Ex.: Mensagem falsa sobre entrega"/></label><label>URL suspeita <span className="optional">opcional</span><input type="url" value={reportUrl} onChange={e=>setReportUrl(e.target.value)} placeholder="https://..."/></label><label>O que aconteceu?<textarea required rows={4} maxLength={4000} value={reportDescription} onChange={e=>setReportDescription(e.target.value)} placeholder="Descreva como você identificou a situação suspeita..."/></label><label className="evidence-picker">Evidências <span className="optional">opcional · até 3 arquivos, 5 MB cada</span><input type="file" accept="image/png,image/jpeg,image/webp,application/pdf" multiple onChange={e=>{const files=Array.from(e.target.files??[]);if(files.length>3||files.some(file=>file.size>5*1024*1024)){flash('Selecione até 3 arquivos de no máximo 5 MB cada.');e.currentTarget.value='';return}setEvidenceFiles(files)}}/>{evidenceFiles.length>0&&<span className="evidence-list">{evidenceFiles.map(file=>file.name).join(' · ')}</span>}<small>Arquivos privados, vinculados à sua denúncia. PNG, JPG, WEBP ou PDF · até 3 arquivos.</small></label><div className="form-privacy"><LockKeyhole size={15}/> Seus dados ficam privados e a denúncia não será confirmada automaticamente.</div><div className="modal-actions"><button type="button" className="secondary-button" onClick={()=>setReportForm(false)}>Cancelar</button><button className="primary-button" disabled={reportBusy}><Send size={15}/>{reportBusy?'Enviando…':'Enviar denúncia'}</button></div></form></section></div>}
  </div>
}

function Overview({userName,analyses,onScanner,onHistory}:{userName:string;analyses:AnalysisRecord[];onScanner:()=>void;onHistory:()=>void}){const threats=analyses.filter(row=>row.risk_score>=65);const lineData=getAnalysisTrend(analyses);const categoryData=getAnalysisCategories(analyses);const riskData=getRiskDistribution(analyses);return <><div className="welcome-row"><div><div className="eyebrow">{new Date().toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})} <span className="live-chip"><span className="status-dot"/> SEU RESUMO</span></div><h1>Olá, {userName}</h1><p>Acompanhe suas análises e verifique conteúdos suspeitos antes de interagir.</p></div><button className="primary-button" onClick={onScanner}><Radar size={17}/> Nova análise</button></div><section className="protection-hero"><div className="hero-grid"/><div className="hero-orbit hero-orbit-a"/><div className="hero-orbit hero-orbit-b"/><div className="hero-shield"><div className="shield-rings"><div className="shield-core"><ShieldCheck size={37}/></div></div><span className="orbit-point p1"/><span className="orbit-point p2"/><span className="orbit-point p3"/></div><div className="hero-copy"><span className="hero-kicker"><span className="status-dot"/> DIGITAL PROTECTION STATUS</span><h2>Pronto para verificar</h2><p>O VigIA analisa conteúdos sob demanda e não monitora sua navegação.</p><div className="hero-meta"><span><Check size={14}/> Análise sob demanda</span><span><Check size={14}/> Histórico privado</span></div></div><div className="hero-score"><div className="score-ring"><div><strong>{analyses.length?Math.round(analyses.reduce((sum,row)=>sum+row.risk_score,0)/analyses.length):'—'}</strong><span>{analyses.length?'/100':''}</span></div></div><span>Risco médio estimado</span><small>{analyses.length?`${analyses.length} análise(s)`:'Sem análises'}</small></div><div className="hero-footnote"><span className="pulse-dot"/> {analyses[0]?`Última análise ${new Date(analyses[0].created_at).toLocaleString('pt-BR')}`:'Ainda não há análises registradas'}</div></section><div className="metrics-grid"><Metric label="Análises realizadas" value={String(analyses.length)} change="total" icon={Radar}/><Metric label="Risco elevado" value={String(threats.length)} change="estimado" icon={ShieldAlert} tone="red"/><Metric label="URLs analisadas" value={String(analyses.filter(row=>row.content_type==='url').length)} change="total" icon={Globe2} tone="amber"/><Metric label="Mensagens analisadas" value={String(analyses.filter(row=>row.content_type==='message').length)} change="total" icon={MessageSquareWarning} tone="cyan"/></div><div className="dashboard-grid"><Panel title="Atividade de ameaças" subtitle="Últimos 7 dias" action={<button className="text-button" onClick={onHistory}>Ver histórico <ArrowRight size={14}/></button>} className="chart-panel"><div className="chart-legend"><span><i className="legend-dot violet"/> Ameaças detectadas</span><span><i className="legend-dot cyan"/> Análises</span><span className="chart-total">{lineData.reduce((sum,row)=>sum+row.threats,0)} <small>riscos elevados · 7 dias</small></span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={lineData} margin={{top:10,right:6,left:-22,bottom:0}}><defs><linearGradient id="threatFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8b5cf6" stopOpacity={0.26}/><stop offset="100%" stopColor="#8b5cf6" stopOpacity={0}/></linearGradient><linearGradient id="scanFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#22d3ee" stopOpacity={0.12}/><stop offset="100%" stopColor="#22d3ee" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#202a3d" vertical={false}/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill:'#738097',fontSize:11}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#738097',fontSize:10}}/><Tooltip {...chartTooltip}/><Area type="monotone" dataKey="scans" stroke="#22d3ee" fill="url(#scanFill)" strokeWidth={1.6}/><Area type="monotone" dataKey="threats" stroke="#9b74ff" fill="url(#threatFill)" strokeWidth={2.2} activeDot={{r:4,fill:'#9b74ff'}}/></AreaChart></ResponsiveContainer></div></Panel><Panel title="Categorias de ameaças" subtitle="Distribuição por tipo" action={<button className="icon-button" aria-label="Mais opções"><MoreHorizontal size={18}/></button>} className="categories-panel"><div className="donut-area"><div className="donut-chart"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={categoryData} dataKey="value" nameKey="name" innerRadius="70%" outerRadius="94%" paddingAngle={4} stroke="none">{categoryData.map(item=><Cell key={item.name} fill={item.color}/>)}</Pie><Tooltip {...chartTooltip}/></PieChart></ResponsiveContainer><div className="donut-center"><strong>{threats.length}</strong><span>risco elevado</span></div></div><div className="legend-list">{categoryData.map(item=><div key={item.name}><span><i style={{background:item.color}}/>{item.name}</span><strong>{item.value}</strong></div>)}</div></div></Panel><Panel title="Atividades recentes" subtitle="Últimas análises no seu ambiente" action={<button className="text-button" onClick={onHistory}>Ver todas <ArrowRight size={14}/></button>} className="activities-panel"><div className="activity-list">{analyses.slice(0,3).map(row=>{const Icon=row.content_type==='url'?Link2:row.content_type==='image'?FileImage:MessageSquareWarning;const tone=row.risk_score>=85?'red':row.risk_score>=65?'red':row.risk_score>=35?'amber':'green';return <div className="activity-row" key={row.id}><span className={`activity-icon ${tone}`}><Icon size={16}/></span><div className="activity-text"><strong>{row.content_type==='url'?'Análise de URL':row.content_type==='image'?'Análise de imagem':'Análise de mensagem'}</strong><span>{new Date(row.created_at).toLocaleString('pt-BR')}</span></div><span className={`risk-pill ${tone}`}>{riskLabels[row.risk_level]}</span></div>})}{analyses.length===0&&<div className="table-note">As análises salvas nesta conta aparecerão aqui.</div>}</div></Panel><Panel title="Recomendações de segurança" subtitle="Pequenos hábitos fazem diferença" action={<span className="recommendation-count">3 dicas</span>} className="recommend-panel"><div className="recommend-list">{recommendations.map((item,i)=><div className="recommend-item" key={item}><span className="recommend-number">0{i+1}</span><p>{item}</p><ChevronRight size={15}/></div>)}</div></Panel></div><Panel title="Distribuição de risco" subtitle="Classificação ilustrativa das ameaças"><div className="risk-distribution compact-risk">{riskData.map(r=><div className="risk-distribution-row" key={r.name}><span><i style={{background:r.color}}/>{r.name}</span><strong>{r.value}%</strong><div><i style={{width:`${r.value*2}%`,background:r.color}}/></div></div>)}</div></Panel><div className="demo-note"><Sparkles size={15}/><span>Os indicadores exibem somente análises desta conta. A pontuação é uma estimativa e não confirma fraude.</span></div></>}

function Scanner({tab,setTab,scanText,setScanText,scanning,scanStep,result,analysisResult,extractedText,startScan,selectedFile,filePreview,fileRef,selectFile,clearFile}:{tab:'url'|'message'|'image';setTab:(value:'url'|'message'|'image')=>void;scanText:string;setScanText:(value:string)=>void;scanning:boolean;scanStep:string;result:boolean;analysisResult:AnalysisResponse|null;extractedText:string;startScan:()=>void;selectedFile:File|null;filePreview:string;fileRef:React.RefObject<HTMLInputElement|null>;selectFile:(file?:File)=>void;clearFile:()=>void}){const titles={url:'Analise um link suspeito',message:'Analise uma mensagem suspeita',image:'Analise uma captura de tela'};const placeholders={url:'Cole a URL que deseja verificar…',message:'Cole a mensagem que você recebeu…',image:''};return <><SectionTitle eyebrow="ANÁLISE INTELIGENTE" title="Intelligent Threat Scanner" description="Analise conteúdos suspeitos antes que possam comprometer sua segurança." action={<span className="demo-label"><span className="status-dot"/> IA + OCR local</span>}/><div className="scanner-layout"><div className="scanner-main"><div className="scanner-tabs" role="tablist" aria-label="Tipo de análise">{([{key:'url',label:'URL Scanner',icon:Link2},{key:'message',label:'Message Scanner',icon:MessageSquareWarning},{key:'image',label:'Image Scanner',icon:ImagePlus}] as const).map(item=>{const Icon=item.icon;return <button role="tab" aria-selected={tab===item.key} className={tab===item.key?'selected':''} key={item.key} onClick={()=>{setTab(item.key);setScanText('')}}><Icon size={17}/>{item.label}</button>})}</div><div className="scan-card"><div className="scan-card-icon">{tab==='url'?<Link2 size={20}/>:tab==='message'?<MessageSquareWarning size={20}/>:<FileImage size={20}/>}</div><div className="eyebrow">VIGIA · {tab==='url'?'VERIFICAÇÃO DE DOMÍNIO':tab==='message'?'ANÁLISE DE TEXTO':'VISÃO COMPUTACIONAL'}</div><h2>{titles[tab]}</h2><p>{tab==='url'?'Verifique sinais e reputação antes de acessar um endereço.':tab==='message'?'Identifique padrões de urgência, solicitações e indicadores de engenharia social.':'Envie uma captura de conversas, e-mails ou páginas suspeitas.'}</p>{tab==='image'?<><button type="button" className={`upload-zone ${selectedFile?'has-file':''}`} onClick={()=>fileRef.current?.click()} onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();selectFile(e.dataTransfer.files[0])}}><input ref={fileRef} type="file" accept="image/png,image/jpeg,image/webp" hidden onChange={e=>selectFile(e.target.files?.[0])}/>{selectedFile&&filePreview?<><img src={filePreview} alt="Prévia da imagem selecionada" className="image-preview"/><span className="file-name">{selectedFile.name} · {(selectedFile.size/1024).toFixed(0)} KB</span><span className="remove-file" onClick={e=>{e.stopPropagation();clearFile()}}><X size={14}/> Remover</span></>:<><span className="upload-icon"><Upload size={20}/></span><strong>Arraste uma imagem ou <em>escolha um arquivo</em></strong><span>PNG, JPG ou WEBP · até 5 MB</span></>}</button></>:<><textarea className="scan-input" rows={tab==='url'?2:6} value={scanText} onChange={e=>setScanText(e.target.value)} placeholder={placeholders[tab]} aria-label={tab==='url'?'URL suspeita':'Mensagem recebida'}/>{tab==='url'&&<div className="example-links"><span>Experimente:</span>{['https://portal-seguro.exemplo.com','https://rastreio-entrega.exemplo.net'].map(link=><button key={link} onClick={()=>setScanText(link)}>{link}</button>)}</div>}</>}<button className="primary-button scan-submit" onClick={startScan} disabled={scanning}>{scanning?<><span className="spinner"/> Analisando conteúdo…</>:<>{tab==='url'?<Link2 size={17}/>:tab==='message'?<Sparkles size={17}/>:<Eye size={17}/>} {tab==='url'?'Analisar URL':tab==='message'?'Analisar mensagem':'Analisar imagem'} <ArrowRight size={16}/></>}</button><div className="scan-privacy"><LockKeyhole size={14}/> Seus dados são processados com segurança. Não abra links suspeitos.</div></div>{scanning&&<div className="processing-card"><div className="processing-head"><span className="spinner"/><div><strong>Análise em andamento</strong><span>{scanStep}</span></div><span className="processing-pct">{scanStep}</span></div><div className="processing-bar"><i/></div><div className="processing-steps"><span className="current"><span className="spinner mini"/>{scanStep}</span></div></div>}{result&&analysisResult&&<AnalysisResultPanel result={analysisResult} extractedText={extractedText} filePreview={filePreview}/>}</div><aside className="scanner-aside"><div className="scanner-aside-head"><span className="scanner-aside-icon"><ShieldCheck size={18}/></span><div><strong>Como funciona</strong><span>Proteção em cada etapa</span></div></div><div className="scan-flow">{[{icon:Globe2,title:'Validação',text:'Formato e estrutura do conteúdo'},{icon:Network,title:'Inteligência',text:'Sinais e padrões observáveis'},{icon:Cpu,title:'Classificação',text:'Indicadores de risco demonstrativos'}].map((item,i)=>{const Icon=item.icon;return <div className="flow-step" key={item.title}><span className="flow-icon"><Icon size={16}/></span><div><strong>{item.title}</strong><span>{item.text}</span></div>{i<2&&<span className="flow-line"/>}</div>})}</div><div className="scanner-tip"><span><CircleHelp size={15}/></span><div><strong>Uma análise não é garantia</strong><p>Os sinais apresentados são ilustrativos. Confirme informações por canais oficiais e não compartilhe dados sensíveis.</p></div></div><div className="demo-badge"><span className="demo-dot"/> IA + OCR REAL</div></aside></div></>}

function ScanResult({tab,content,fileName}:{tab:string;content:string;fileName?:string}){const high=tab==='url'&&/exemplo\.net|pagamento/i.test(content);const score=high?87:tab==='message'?81:tab==='image'?74:29;return <section className="scan-result"><div className="result-head"><div><span className="eyebrow">RELATÓRIO DE ANÁLISE · DEMONSTRATIVO</span><h3>Resultado da análise</h3></div><span className={`classification ${score>70?'high':'low'}`}><span className="risk-dot"/>{score>70?'RISCO ELEVADO':'BAIXO RISCO'}</span></div><div className="result-overview"><div className={`result-score ${score>70?'danger':''}`}><div><strong>{score}</strong><span>/100</span></div></div><div className="result-target"><span>Conteúdo avaliado</span><strong>{fileName||content||'Conteúdo demonstrativo'}</strong><small><Globe2 size={14}/> Classificação ilustrativa · não é verificação real</small></div><div className="result-confidence"><span>Confiança do exemplo</span><strong>92%</strong><small>Não é validação real</small></div><div className="result-confidence"><span>Duração ilustrativa</span><strong>1,4 s</strong><small>Processamento simulado</small></div></div><div className="result-details"><div><span>HTTPS</span><strong>Não verificado</strong></div><div><span>Reputação do domínio</span><strong>Não consultada</strong></div><div><span>Redirecionamentos</span><strong>Não examinados</strong></div></div>{tab==='image'&&<div className="ocr-demo"><span className="eyebrow">EXTRAÇÃO DE TEXTO · EXEMPLO VISUAL</span><p>{'“Sua conta será bloqueada. Confirme seus dados agora.”'}</p><small>Texto ilustrativo: OCR real não está conectado nesta demonstração.</small></div>}{tab==='message'&&<div className="ocr-demo"><span className="eyebrow">POR QUE ESTA MENSAGEM PARECE SUSPEITA?</span><p>A urgência e o pedido para acessar um link podem ser sinais de tentativa de engenharia social.</p><small>Explicação demonstrativa, não gerada por inteligência artificial.</small></div>}<div className="result-indicators">{[{title:'Sinais de urgência',text:'Linguagem que pode pressionar uma decisão rápida.',icon:Zap},{title:'Origem não verificada',text:'A origem precisa ser conferida por canal independente.',icon:Globe2},{title:'Solicitação de dados',text:'Nunca compartilhe senhas ou códigos de confirmação.',icon:KeyRound}].slice(0,score>70?3:1).map(item=>{const Icon=item.icon;return <div className="indicator-card" key={item.title}><span><Icon size={15}/></span><div><strong>{item.title}</strong><p>{item.text}</p></div></div>})}</div><div className="result-advice"><ShieldCheck size={17}/><span><strong>Como agir:</strong> evite interagir, não informe dados pessoais e confirme a solicitação em um canal oficial conhecido.</span></div><div className="result-disclaimer">Este resultado é uma simulação visual. O VigIA ainda não consulta serviços reais de reputação, IA ou OCR.</div></section>}

function HistoryPage({analyses,onScan}:{analyses:AnalysisRecord[];onScan:()=>void}){return <><SectionTitle eyebrow="REGISTRO DE ATIVIDADE" title="Histórico de análises" description="Acompanhe as verificações realizadas na sua conta."/><Panel title="Atividades recentes" subtitle={`${analyses.length} análise(s) registrada(s)`}>{analyses.length===0?<div className="empty-state"><span><FileClock size={24}/></span><h3>Nenhuma análise ainda</h3><p>As análises concluídas serão salvas aqui, sem armazenar o conteúdo original.</p><button className="primary-button" onClick={onScan}>Iniciar análise <ArrowRight size={15}/></button></div>:<><div className="history-table"><div className="table-head"><span>TIPO</span><span>CONTEÚDO</span><span>RISCO</span><span>DATA</span><span>STATUS</span></div>{analyses.map(row=>{const Icon=row.content_type==='url'?Link2:row.content_type==='image'?FileImage:MessageSquareWarning;const tone=row.risk_score>=65?'red':row.risk_score>=35?'amber':'green';return <div className="table-row" key={row.id}><span className="table-type"><i className={`activity-icon ${tone}`}><Icon size={15}/></i>{row.content_type==='url'?'URL':row.content_type==='image'?'Imagem':'Mensagem'}</span><strong>{row.risk_score}/100 · risco estimado</strong><span className={`risk-pill ${tone}`}>{riskLabels[row.risk_level]}</span><span>{new Date(row.created_at).toLocaleString('pt-BR')}</span><span className="status-complete"><CheckCircle2 size={14}/> {row.processing_status==='completed'?'Concluída':'Parcial'}</span></div>})}</div><div className="table-note">O conteúdo enviado não é armazenado. Os registros são privados da sua conta.</div></>}</Panel>{analyses.length>0&&<div className="empty-action"><FileClock size={20}/><div><strong>Precisa verificar algo novo?</strong><span>Inicie uma análise para acompanhar sinais de segurança.</span></div><button className="primary-button" onClick={onScan}>Nova análise <ArrowRight size={15}/></button></div>}</>}

function Intelligence({analyses}:{analyses:AnalysisRecord[]}){const lineData=getAnalysisTrend(analyses);const categoryData=getAnalysisCategories(analyses);const riskData=getRiskDistribution(analyses);const elevated=analyses.filter(row=>row.risk_score>=65).length;const topCategory=categoryData[0]?.name??'—';return <><SectionTitle eyebrow="DADOS PRIVADOS DA CONTA" title="Threat Intelligence Center" description="Tendências calculadas a partir das suas análises salvas." action={<span className="demo-label"><span className="status-dot"/> Dados da conta</span>}/><div className="metrics-grid four"><Metric label="Análises registradas" value={String(analyses.length)} change="total" icon={Radar}/><Metric label="Risco elevado estimado" value={String(elevated)} change="pontuação ≥ 65" icon={ShieldAlert} tone="red"/><Metric label="Indicador recorrente" value={topCategory} change="da sua conta" icon={MessageSquareWarning}/><Metric label="Imagens analisadas" value={String(analyses.filter(row=>row.content_type==='image').length)} change="total" icon={FileImage} tone="cyan"/></div><div className="dashboard-grid intel-grid"><Panel title="Evolução de ameaças" subtitle="Suas análises · últimos 7 dias" className="chart-panel"><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><AreaChart data={lineData} margin={{top:14,right:12,left:-18,bottom:0}}><defs><linearGradient id="intelFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#22d3ee" stopOpacity={.2}/><stop offset="100%" stopColor="#22d3ee" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#202a3d" vertical={false}/><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{fill:'#738097',fontSize:11}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#738097',fontSize:10}}/><Tooltip {...chartTooltip}/><Area dataKey="threats" type="monotone" stroke="#22d3ee" fill="url(#intelFill)" strokeWidth={2.3}/></AreaChart></ResponsiveContainer></div></Panel><Panel title="Severidade das ameaças" subtitle="Distribuição por nível" className="risk-panel"><div className="risk-distribution">{riskData.map(r=><div className="risk-distribution-row" key={r.name}><span><i style={{background:r.color}}/>{r.name}</span><strong>{r.value}%</strong><div><i style={{width:`${r.value*2}%`,background:r.color}}/></div></div>)}</div><div className="table-note">Distribuição estimada pelas análises desta conta; não representa uma confirmação independente de ameaça.</div></Panel><Panel title="Categorias mais reportadas" subtitle="Volume relativo por categoria" className="chart-panel"><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={categoryData} margin={{top:10,right:12,left:-18,bottom:0}}><CartesianGrid stroke="#202a3d" vertical={false}/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:'#738097',fontSize:10}}/><YAxis axisLine={false} tickLine={false} tick={{fill:'#738097',fontSize:10}}/><Tooltip {...chartTooltip}/><Bar dataKey="value" radius={[5,5,0,0]}>{categoryData.map(d=><Cell key={d.name} fill={d.color}/>)}</Bar></BarChart></ResponsiveContainer></div></Panel><Panel title="Padrões emergentes" subtitle="Sinais acompanhados na amostra" className="emerging-panel">{['Aumento de mensagens com senso de urgência','Maior recorrência de páginas de pagamento falsas','Reutilização de domínios com pequenas variações','Tentativas de contato fora dos canais oficiais'].map((text,i)=><div className="emerging-row" key={text}><span className="emerging-num">0{i+1}</span><span>{text}</span><ArrowUpRight size={14}/></div>)}</Panel></div><div className="geo-demo"><div className="geo-map-art"><div className="map-grid"/><span className="map-pulse one"/><span className="map-pulse two"/><span className="map-pulse three"/><span className="map-pulse four"/></div><div><span className="eyebrow">VISUALIZAÇÃO ILUSTRATIVA</span><h3>Distribuição geográfica</h3><p>Uma representação fictícia de tendências agregadas. Não exibe nem utiliza a localização de usuários.</p></div><span className="demo-label"><span className="demo-dot"/> Sem dados reais</span></div></>}

function Education({score,setScore,choice,setChoice}:{score:number|null;setScore:(n:number)=>void;choice:string;setChoice:(s:string)=>void}){function answer(value:string){setChoice(value);setScore(value==='suspeita'?1:0)}return <><SectionTitle eyebrow="APRENDA A SE PROTEGER" title="Digital Security Academy" description="Conhecimento acessível para reconhecer ameaças e proteger suas informações." action={<div className="learning-progress"><GraduationCap size={16}/><span>Seu progresso</span><strong>{score===null?'0':score?'1':'0'} / 6</strong></div>}/><div className="lesson-grid">{lessons.map((lesson,i)=>{const Icon=lesson.icon;return <article className="lesson-card" key={lesson.title}><span className={`lesson-icon ${lesson.color}`}><Icon size={19}/></span><span className="lesson-time"><BookOpen size={12}/>{lesson.tag} de leitura</span><h3>{lesson.title}</h3><p>{lesson.text}</p><button className="text-button" onClick={()=>answer('')}>Explorar conteúdo <ArrowRight size={14}/></button><span className="lesson-index">0{i+1}</span></article>})}</div><Panel title="Teste seu olhar" subtitle="Situação fictícia · escolha a opção mais segura" className="quiz-panel"><div className="quiz-question"><span className="quiz-bubble"><MessageSquareWarning size={18}/></span><div><span className="eyebrow">MENSAGEM RECEBIDA</span><p>“Sua conta será bloqueada em 30 minutos. Acesse este link para confirmar seus dados agora.”</p></div></div><div className="quiz-options"><button className={choice==='legitima'?'chosen':''} onClick={()=>answer('legitima')}><span>A</span> Parece legítima</button><button className={choice==='suspeita'?'chosen':''} onClick={()=>answer('suspeita')}><span>B</span> Parece suspeita</button></div>{score!==null&&<div className={`quiz-feedback ${score?'correct':'incorrect'}`}><CheckCircle2 size={17}/><div><strong>{score?'Boa observação!':'Vamos analisar juntos.'}</strong><span>Urgência e pedido para acessar um link são sinais de alerta. Confirme sempre por um canal oficial.</span></div><strong>{score?'+10 pontos':'Continue aprendendo'}</strong></div>}</Panel><div className="education-note"><ShieldCheck size={17}/><span>A educação digital amplia a proteção de toda a comunidade. O material apresentado é demonstrativo.</span></div></>}

function Reports({onOpen,onMine}:{onOpen:()=>void;onMine:()=>void}){return <><SectionTitle eyebrow="SEGURANÇA COLABORATIVA" title="Denunciar ameaça" description="Ajude a tornar a internet mais segura. Compartilhe indícios de golpes para contribuir com a identificação de ameaças digitais." action={<button className="primary-button" onClick={onOpen}><Send size={16}/> Registrar denúncia</button>}/><div className="report-intro"><div className="report-intro-icon"><ShieldAlert size={24}/></div><div><h2>Identificou um possível golpe?</h2><p>Suas informações são tratadas de forma privada. Uma denúncia recebida não significa que a ameaça foi confirmada.</p></div><button className="secondary-button" onClick={onMine}>Acompanhar denúncias <ArrowRight size={15}/></button></div><div className="report-category-grid">{[{icon:Globe2,title:'Site fraudulento',text:'Páginas falsas e domínios suspeitos.'},{icon:Building2,title:'Golpe bancário',text:'Falsas centrais, transferências e boletos.'},{icon:MailIcon,title:'Phishing',text:'Mensagens para capturar dados.'},{icon:MessageSquareWarning,title:'Golpe pelo WhatsApp',text:'Contatos e mensagens suspeitas.'},{icon:CircleHelp,title:'Falso suporte técnico',text:'Golpistas se passando por assistência.'},{icon:KeyRound,title:'Roubo de dados pessoais',text:'Tentativas de obter dados ou senhas.'},{icon:ArrowUpRight,title:'Falso investimento',text:'Promessas de retorno garantido.'},{icon:MoreHorizontal,title:'Outros golpes digitais',text:'Conte casos que não se encaixam acima.'}].map(item=>{const Icon=item.icon;return <button className="report-category" key={item.title} onClick={onOpen}><span><Icon size={18}/></span><strong>{item.title}</strong><small>{item.text}</small><ChevronRight size={15}/></button>})}</div><div className="report-privacy"><LockKeyhole size={16}/><div><strong>Privacidade em primeiro lugar</strong><span>Não inclua senhas, códigos de acesso ou dados pessoais de terceiros na descrição ou em evidências.</span></div><button className="text-button" onClick={()=>onOpen()}>Saiba como <ArrowRight size={14}/></button></div></>}

function MyReports({reports,signedIn,onLogin,onReport,onRefresh,onToast}:{reports:Record<string,unknown>[];signedIn:boolean;onLogin:()=>void;onReport:()=>void;onRefresh:()=>void;onToast:(message:string)=>void}){return <><SectionTitle eyebrow="ACOMPANHAMENTO PRIVADO" title="Minhas denúncias" description="Consulte o andamento das informações que você compartilhou." action={<button className="secondary-button" onClick={onRefresh}><Activity size={15}/> Atualizar</button>}/>{!signedIn?<div className="empty-state"><span><LockKeyhole size={24}/></span><h3>Entre para acessar suas denúncias</h3><p>As informações são privadas e visíveis somente na sua conta.</p><button className="primary-button" onClick={onLogin}>Entrar na conta <ArrowRight size={15}/></button></div>:reports.length===0?<div className="empty-state"><span><FileClock size={24}/></span><h3>Nenhuma denúncia encontrada</h3><p>Quando você enviar uma denúncia, poderá acompanhar as atualizações por aqui.</p><button className="primary-button" onClick={onReport}>Registrar denúncia <Send size={15}/></button></div>:<Panel title="Suas denúncias" subtitle={`${reports.length} registro(s)`}><div className="history-table"><div className="table-head"><span>CÓDIGO</span><span>TIPO DE AMEAÇA</span><span>DATA</span><span>PLATAFORMA</span><span>STATUS</span></div>{reports.map(r=><div className="table-row" key={String(r.id)}><span className="mono-id">VG-{String(r.id).slice(0,6).toUpperCase()}</span><strong>{String(r.category)}</strong><span>{new Date(String(r.created_at)).toLocaleDateString('pt-BR')}</span><span>{String(r.platform)}</span><span className="risk-pill amber">{statusLabel[String(r.status)]??'Recebida'}</span>{Array.isArray(r.attachments)&&r.attachments.length>0&&<div className="report-evidence-links"><span>Evidências:</span>{r.attachments.map((attachment,index)=>{const file=attachment as {file_name:string;storage_path:string;signed_url:string};return <button key={`${file.storage_path}-${index}`} type="button" onClick={()=>{if(!file.signed_url){onToast('Não foi possível abrir esta evidência. Atualize a lista e tente novamente.');return}window.open(file.signed_url,'_blank','noopener,noreferrer')}}><FileText size={13}/>{file.file_name}</button>})}</div>}</div>)}</div><div className="table-note">Denúncias são analisadas pela equipe; o envio não confirma automaticamente uma ameaça.</div></Panel>}</>}

function Plans({onAction}:{onAction:()=>void}){const plans=[{name:'Gratuito',price:'R$ 0',period:'para sempre',description:'Proteção essencial para começar a navegar com mais segurança.',color:'green',features:['Dashboard e educação digital','Análises limitadas de URL e mensagens','Envio de denúncias','Histórico básico']},{name:'Mensal',price:'Configurável',period:'cobrança mensal',description:'Mais liberdade para analisar ameaças no dia a dia.',color:'cyan',features:['Limites ampliados de análise','Histórico estendido','Relatórios de análise','Recursos avançados']},{name:'Anual',price:'Configurável',period:'cobrança anual',description:'Proteção contínua com condição anual.',color:'purple',features:['Recursos do plano individual pago','Histórico estendido','Relatórios avançados','Condição comercial anual']},{name:'Premium',price:'Configurável',period:'individual',description:'Uma experiência avançada de proteção e inteligência digital.',color:'premium',featured:true,features:['Limites superiores de análise','Análises avançadas','Histórico completo','Indicadores de inteligência']},{name:'Business',price:'Sob consulta',period:'para equipes',description:'Segurança digital e inteligência para empresas.',color:'business',features:['Gestão de equipes e permissões','Painel administrativo','Relatórios consolidados','Integração via API'] }];return <><SectionTitle eyebrow="CONTA E ASSINATURA" title="Meu plano" description="Acompanhe recursos, limites e opções de assinatura." action={<span className="demo-label"><span className="demo-dot"/> Preços configuráveis</span>}/><div className="current-plan"><div><span className="current-plan-icon"><ShieldCheck size={18}/></span><div><span className="eyebrow">SEU PLANO ATUAL</span><h2>Gratuito <span className="plan-status">Ativo</span></h2><p>Proteção essencial para começar com segurança.</p></div></div><div className="usage-mini"><span>Utilização mensal <strong>68%</strong></span><div className="usage-bar"><i style={{width:'68%'}}/></div><small>Os limites são exemplos demonstrativos.</small></div></div><div className="plans-grid">{plans.map(plan=><article className={`plan-card ${plan.featured?'featured':''}`} key={plan.name}><div className={`plan-tag ${plan.color}`}>{plan.featured?'RECOMENDADO':plan.name.toUpperCase()}</div><h3>{plan.name}</h3><p>{plan.description}</p><div className="plan-price">{plan.price}<small>{plan.period}</small></div><div className="plan-divider"/><ul>{plan.features.map(f=><li key={f}><Check size={14}/>{f}</li>)}</ul><button className={plan.name==='Gratuito'?'secondary-button':'primary-button'} onClick={onAction} disabled={plan.name!=='Gratuito'}>{plan.name==='Gratuito'?'Plano atual':'Indisponível sem integração de pagamento'}{plan.name==='Gratuito'&&<Check size={14}/>}</button></article>)}</div><div className="billing-note"><LockKeyhole size={15}/><span>Nenhuma cobrança real é realizada neste protótipo. A contratação depende de integração de pagamentos e confirmação segura no backend.</span></div></>}

function SettingsPage({user,tab,setTab,onLogin,onToast}:{user:SessionUser|null;tab:string;setTab:(v:string)=>void;onLogin:()=>void;onToast:(s:string)=>void}){const defaults={threats:true,reports:true,security:true,news:false,billing:true};const [notifications,setNotifications]=useState(defaults);const [name,setName]=useState(user?.name??'');const [saving,setSaving]=useState(false);const [exporting,setExporting]=useState(false);const {data:profile}=useSWR(user?['profile-settings',user.id]:null,async()=>{const {data,error}=await createClient().from('profiles').select('display_name,notification_settings').eq('id',user!.id).maybeSingle();if(error)throw error;return data});useEffect(()=>{if(profile){setName(profile.display_name??user?.name??'');setNotifications({...defaults,...(profile.notification_settings as Partial<typeof defaults>|null)})}},[profile,user?.id]);async function save(){if(!user){onLogin();return}const normalizedName=name.trim();if(!normalizedName||normalizedName.length>80){onToast('Informe um nome com até 80 caracteres.');return}setSaving(true);const supabase=createClient();const [{error},{error:authError}]=await Promise.all([supabase.from('profiles').upsert({id:user.id,display_name:normalizedName,notification_settings:notifications,updated_at:new Date().toISOString()},{onConflict:'id'}),supabase.auth.updateUser({data:{display_name:normalizedName}})]);setSaving(false);onToast(error||authError?'Não foi possível salvar todas as alterações.':'Preferências salvas na sua conta.')}async function exportData(){if(!user){onLogin();return}setExporting(true);try{const supabase=createClient();const [profileResult,analysesResult,reportsResult,attachmentsResult,subscriptionsResult,usageResult]=await Promise.all([supabase.from('profiles').select('*').eq('id',user.id).maybeSingle(),supabase.from('analyses').select('*').order('created_at',{ascending:false}),supabase.from('reports').select('*').order('created_at',{ascending:false}),supabase.from('report_attachments').select('*'),supabase.from('subscriptions').select('*'),supabase.from('usage_records').select('*')]);const error=[profileResult.error,analysesResult.error,reportsResult.error,attachmentsResult.error,subscriptionsResult.error,usageResult.error].find(Boolean);if(error)throw error;const payload={exportedAt:new Date().toISOString(),profile:profileResult.data,analyses:analysesResult.data??[],reports:reportsResult.data??[],reportAttachments:attachmentsResult.data??[],subscriptions:subscriptionsResult.data??[],usageRecords:usageResult.data??[]};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`vigia-dados-${new Date().toISOString().slice(0,10)}.json`;link.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000);onToast('Exportação dos dados da sua conta iniciada.')}catch{onToast('Não foi possível exportar todos os dados. Tente novamente.')}finally{setExporting(false)}}return <><SectionTitle eyebrow="PERFIL E PREFERÊNCIAS" title="Configurações" description="Gerencie suas informações e preferências de segurança."/><div className="settings-layout"><div className="settings-tabs">{[{key:'profile',label:'Informações pessoais',icon:UserRound},{key:'security',label:'Segurança da conta',icon:LockKeyhole},{key:'notifications',label:'Notificações',icon:Bell},{key:'privacy',label:'Privacidade e dados',icon:ShieldCheck}].map(item=>{const Icon=item.icon;return <button className={tab===item.key?'active':''} key={item.key} onClick={()=>setTab(item.key)}><Icon size={16}/>{item.label}<ChevronRight size={14}/></button>})}</div><Panel title={tab==='profile'?'Informações pessoais':tab==='security'?'Segurança da conta':tab==='notifications'?'Preferências e notificações':'Privacidade e dados'} subtitle={tab==='profile'?'Atualize os dados associados ao seu perfil.':'Suas preferências são privadas e vinculadas à conta.'} className="settings-panel">{tab==='profile'?<><div className="settings-avatar"><span className="avatar large">{(user?.name||'G').slice(0,1).toUpperCase()}</span><div><strong>{user?.name||'Visitante'}</strong><span>{user?.email||'Entre para editar os dados da sua conta.'}</span></div></div><label className="settings-field">Nome completo<input value={name} onChange={e=>setName(e.target.value)} disabled={!user}/></label><label className="settings-field">E-mail<input value={user?.email??'—'} disabled/></label><div className="settings-field"><span className="field-label">Plano</span><div className="readonly-value">Gratuito · Plano inicial</div></div><button className="primary-button" onClick={()=>void save()} disabled={saving}>{saving?'Salvando…':'Salvar alterações'}</button>{!user&&<p className="settings-hint"><LockKeyhole size={13}/> Entre para editar suas informações pessoais.</p>}</>:tab==='security'?<div className="settings-empty"><KeyRound size={22}/><strong>Segurança gerenciada pela sua conta</strong><span>Use a recuperação de senha para atualizar seu acesso com segurança.</span><a href="/auth/recuperar" className="secondary-button">Redefinir senha <ArrowRight size={14}/></a></div>:tab==='notifications'?<><div className="switch-list">{[{key:'threats',title:'Novas ameaças',text:'Avisos sobre tendências de segurança.'},{key:'reports',title:'Atualizações de denúncias',text:'Mudanças no andamento das suas denúncias.'},{key:'security',title:'Alertas de segurança',text:'Atividade importante relacionada à conta.'},{key:'news',title:'Novidades da plataforma',text:'Novas ferramentas e conteúdos educativos.'},{key:'billing',title:'Comunicações do plano',text:'Informações relacionadas à sua assinatura.'}].map(item=><label className="switch-row" key={item.key}><span><strong>{item.title}</strong><small>{item.text}</small></span><input type="checkbox" checked={notifications[item.key as keyof typeof notifications]} onChange={e=>setNotifications(prev=>({...prev,[item.key]:e.target.checked}))}/></label>)}</div><button className="primary-button" onClick={()=>void save()} disabled={saving}>{saving?'Salvando…':'Salvar preferências'}</button></>:<div className="privacy-list"><div><ShieldCheck size={18}/><span><strong>Seus dados são privados</strong><small>Denúncias vinculadas à sua conta não ficam públicas.</small></span></div><div><Download size={18}/><span><strong>Solicitar exportação</strong><small>Peça uma cópia das informações da sua conta.</small></span><button className="text-button" onClick={()=>void exportData()} disabled={exporting}>{exporting?'Preparando…':'Baixar JSON'}</button></div><div><AlertTriangle size={18}/><span><strong>Solicitar exclusão da conta</strong><small>A exclusão remove os dados associados à sua conta.</small></span><button className="text-button danger-text" onClick={()=>onToast('Entre em contato com o suporte para solicitar a exclusão de dados.')}>Saiba mais</button></div><p>O gerenciamento completo de dados e exclusão definitiva deve ser validado pelo servidor antes de entrar em produção.</p></div>}</Panel></div></>}

function Infrastructure(){const nodes=[{icon:LayoutDashboard,title:'Aplicação Web',tech:'Frontend · Next.js',state:'Demonstração',color:'purple'},{icon:Network,title:'API Gateway',tech:'Spring Cloud Gateway',state:'Planejado',color:'cyan'},{icon:Cpu,title:'Serviços de análise',tech:'Spring Boot · REST',state:'Planejado',color:'purple'},{icon:Bot,title:'Processamento IA',tech:'Python · modelos de análise',state:'Não conectado',color:'cyan'},{icon:Building2,title:'Banco de dados',tech:'PostgreSQL · Supabase',state:'Conectado',color:'green'},{icon:Cloud,title:'Cloud Storage',tech:'AWS · evidências privadas',state:'Planejado',color:'amber'}];return <><SectionTitle eyebrow="ARQUITETURA CONCEITUAL" title="Cloud Infrastructure" description="Visão da arquitetura planejada do VigIA. Componentes não conectados são identificados como planejados." action={<span className="demo-label"><span className="demo-dot"/> Estado ilustrativo</span>}/><Panel title="Fluxo de processamento" subtitle="Componentes propostos para a evolução da plataforma" className="architecture-panel"><div className="architecture-flow">{nodes.map((node,i)=>{const Icon=node.icon;return <div className="architecture-wrap" key={node.title}><article className="architecture-node"><span className={`architecture-icon ${node.color}`}><Icon size={19}/></span><strong>{node.title}</strong><small>{node.tech}</small><span className={`architecture-state ${node.state==='Conectado'?'connected':''}`}>{node.state==='Conectado'?<CheckCircle2 size={12}/>:<span className="demo-dot"/>}{node.state}</span></article>{i<nodes.length-1&&<span className="architecture-arrow"><ArrowRight size={17}/></span>}</div>})}</div></Panel><div className="metrics-grid infra-metrics"><Metric label="API availability" value="—" change="Não conectado" icon={Activity}/><Metric label="Processing status" value="Demo" change="Local" icon={Cpu} tone="cyan"/><Metric label="Storage usage" value="—" change="Não conectado" icon={Cloud} tone="amber"/><Metric label="Cloud resources" value="Planejado" change="AWS" icon={Building2} tone="green"/></div><div className="infra-note"><CircleHelp size={17}/><span>A arquitetura é uma proposta conceitual para evolução com AWS, Spring Boot, PostgreSQL e serviços de IA. Não afirma que recursos em nuvem estejam ativos.</span></div></>}

function Impact(){return <><SectionTitle eyebrow="TECNOLOGIA COM PROPÓSITO" title="Social Impact" description="A tecnologia é o meio. O cidadão está no centro. O impacto positivo é o objetivo."/><div className="ods-grid">{[{n:'04',title:'Educação de qualidade',tag:'ODS 4',text:'Promover oportunidades de aprendizagem e conhecimento digital acessível.',how:'O VigIA oferece conteúdos práticos para reconhecer golpes e navegar com mais confiança.',metric:'Conclusão de trilhas educativas',color:'purple'},{n:'10',title:'Redução das desigualdades',tag:'ODS 10',text:'Contribuir para reduzir vulnerabilidades e ampliar acesso à proteção.',how:'Uma experiência acessível ajuda diferentes públicos a reconhecer riscos digitais.',metric:'Acesso e conclusão por perfil',color:'cyan'},{n:'16',title:'Paz, justiça e instituições eficazes',tag:'ODS 16',text:'Fortalecer segurança, informação e confiança no ambiente digital.',how:'Denúncias colaborativas e educação incentivam uma comunidade mais informada.',metric:'Denúncias encaminhadas para análise',color:'green'}].map(item=><article className={`ods-card ${item.color}`} key={item.tag}><div className="ods-top"><span className="ods-number">{item.n}</span><span>{item.tag}</span></div><h2>{item.title}</h2><p>{item.text}</p><div className="ods-detail"><strong>Como o VigIA contribui</strong><span>{item.how}</span></div><div className="ods-detail"><strong>Indicador de impacto</strong><span>{item.metric}</span></div></article>)}</div><section className="purpose-card"><div className="purpose-symbol"><HeartHandshake size={28}/></div><div><span className="eyebrow">VIGIA · IMPACTO SOCIAL</span><h2>Technology is the tool.<br/><em>People are the priority.</em></h2><p>Digital safety is our mission.</p></div><div className="purpose-mark"><Brand compact/></div></section></>}
